// Deixa passar SOMENTE o evento de status que virou "entregue".
// O before/after pode chegar como string ou como objeto {status: ...} — trata os dois.
const STATUS_ALVO = 'entregue'; // <-- ajustar aqui se o nome exato do status na lista ROTAS for outro

const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  if ((b.event ?? '') !== 'taskStatusUpdated') continue;
  const h = (b.history_items ?? [])[0] ?? {};
  const raw = h.after;
  const after = (raw && typeof raw === 'object' ? raw.status : raw) ?? '';
  if (String(after).trim().toLowerCase() !== STATUS_ALVO) continue;
  out.push({ json: { taskId: b.task_id, statusNovo: String(after) } });
}
return out;

// Confirma que a tarefa é da lista ROTAS e extrai o número do pedido do nome.
// Nome padrão dos cards: "13046 - Alecrim - 13/08/2026" → pedido = 13046.
const LISTA_ALVO = 'ROTAS'; // nome da lista no ClickUp

const out = [];
for (const item of $input.all()) {
  const t = item.json;
  const lista = String(t.list?.name ?? '').trim().toUpperCase();
  if (lista !== LISTA_ALVO) continue; // card de outra lista: ignora em silêncio
  const m = String(t.name ?? '').match(/^\s*(\d+)/);
  if (!m) continue; // nome sem número na frente: não dá para casar com pedido
  out.push({ json: {
    numero: m[1],
    taskId: t.id,
    nomeTarefa: t.name,
  }});
}
return out;

// Traduz numero -> id interno do Tiny e decide se deve alterar a situação.
// NÃO renomear o node 'Validar ROTAS e extrair pedido' — a referência abaixo é pelo nome.
const alvo = $('Validar ROTAS e extrair pedido').first().json;
const numero = String(alvo.numero);

const ret = $input.first().json?.retorno ?? {};
if (ret.status !== 'OK') {
  // codigo_erro 20 = consulta sem registros -> pedido não existe no Tiny
  throw new Error('pedidos.pesquisa falhou para o numero ' + numero + ': ' + JSON.stringify(ret.erros ?? ret.codigo_erro ?? ret));
}

const lista = Array.isArray(ret.pedidos) ? ret.pedidos : (ret.pedidos ? [ret.pedidos] : []);
const pedidos = lista.map((x) => x.pedido || x);
const p = pedidos.find((x) => String(x.numero) === numero);
if (!p) throw new Error('Pedido numero ' + numero + ' nao encontrado no retorno do Tiny (card: ' + alvo.nomeTarefa + ')');

const sit = String(p.situacao ?? '').toLowerCase();
const jaEntregue = sit.includes('entreg') && !sit.includes('nao') && !sit.includes('n\u00e3o');
const cancelado = sit.includes('cancel');

if (jaEntregue) return []; // idempotência: mover o card de novo não repete a chamada
if (cancelado) return [];  // pedido cancelado nunca vira entregue por automação

return [{ json: {
  id: String(p.id),
  numero,
  situacaoAnterior: String(p.situacao ?? ''),
  taskId: alvo.taskId,
  nomeTarefa: alvo.nomeTarefa,
}}];
